// Renders the data-driven sections from data/projects.json.
// Without JavaScript, the <noscript> fallbacks (generated by scripts/sync.py) show the same entries.
(function () {
  'use strict';

  // Photo fallback: show the initials avatar if the image is missing.
  var avatar = document.getElementById('avatar');
  var initials = document.getElementById('avatar-initials');
  function useInitials() {
    if (!avatar || !initials) return;
    avatar.remove();
    initials.hidden = false;
  }
  if (avatar) {
    if (avatar.complete && avatar.naturalWidth === 0) useInitials();
    else avatar.addEventListener('error', useInitials);
  }

  // Small element builder: h('p', {class: 'x'}, 'text', childNode)
  function h(tag, attrs) {
    var el = document.createElement(tag);
    if (attrs) {
      Object.keys(attrs).forEach(function (k) {
        if (attrs[k] !== undefined && attrs[k] !== null && attrs[k] !== false) el.setAttribute(k, attrs[k]);
      });
    }
    for (var i = 2; i < arguments.length; i++) append(el, arguments[i]);
    return el;
  }
  function append(el, child) {
    if (child === undefined || child === null || child === false) return;
    if (Array.isArray(child)) { child.forEach(function (c) { append(el, c); }); return; }
    el.appendChild(typeof child === 'string' ? document.createTextNode(child) : child);
  }

  // Each todo becomes an HTML comment "TODO(Davide): ..." plus, when it has "show", a visible placeholder.
  function todos(list) {
    return (list || []).map(function (t) {
      var nodes = [document.createComment(' TODO(Davide): ' + t.need + ' ')];
      if (t.show) nodes.push(h('span', { class: 'todo' }, t.show));
      return nodes;
    });
  }

  function links(list) {
    if (!list || !list.length) return null;
    return h('ul', { class: 'links' }, list.map(function (l) {
      return h('li', null, h('a', { href: l.url }, l.label));
    }));
  }

  function chips(list) {
    if (!list || !list.length) return null;
    return h('ul', { class: 'chips', 'aria-label': 'Stack' }, list.map(function (s) {
      return h('li', { class: 'chip' }, s);
    }));
  }

  function when(e) { return [e.dates, e.place].filter(Boolean).join(' · '); }

  var render = {
    featured: function (items) {
      return items.map(function (p) {
        return h('article', { class: 'case' + (p.wide ? ' case--wide' : ''), id: 'work-' + p.id },
          h('header', null, h('h3', null, p.title), h('p', { class: 'case__meta' }, p.meta)),
          h('dl', null,
            h('div', null, h('dt', null, 'Problem'), h('dd', null, p.problem)),
            h('div', null, h('dt', null, 'Contribution'), h('dd', null, p.did,
              p.items ? h('ul', { class: 'case__items' }, p.items.map(function (i) { return h('li', null, i); })) : null)),
            h('div', null, h('dt', null, 'Outcome'), h('dd', null, p.outcome))
          ),
          chips(p.stack),
          todos(p.todo),
          (p.demo || (p.links && p.links.length)) ? h('div', { class: 'case__foot' },
            p.demo ? h('a', { class: 'button button--primary case__demo', href: p.demo.url }, p.demo.label) : null,
            links(p.links)) : null
        );
      });
    },

    more: function (items) {
      var groups = [];
      var byName = {};
      items.forEach(function (m) {
        if (!byName[m.group]) { byName[m.group] = []; groups.push(m.group); }
        byName[m.group].push(m);
      });
      return groups.map(function (g) {
        return h('div', { class: 'more-group' },
          groups.length > 1 ? h('h3', null, g) : null,
          h('ul', { class: 'more-grid' }, byName[g].map(function (m) {
            var title = m.url ? h('a', { href: m.url }, m.title) : m.title;
            return h('li', { class: 'more-item' },
              h('div', { class: 'more-item__head' },
                h('span', { class: 'more-item__title' }, title),
                m.years ? h('span', { class: 'more-item__years' }, m.years) : null),
              h('p', null, m.line),
              m.demo ? h('a', { class: 'more-item__demo', href: m.demo.url }, m.demo.label) : null,
              todos(m.todo)
            );
          }))
        );
      });
    },

    // An entry with "roles" is one employer with several roles: the employer is the heading.
    experience: function (items) {
      return items.map(function (e) {
        return h('li', null,
          h('div', { class: 'timeline__role' }, e.role || e.org),
          e.role ? h('div', { class: 'timeline__org' }, e.org) : null,
          h('div', { class: 'timeline__when' }, when(e)),
          e.line ? h('p', { class: 'timeline__line' }, e.line) : null,
          e.roles ? h('ul', { class: 'timeline__roles' }, e.roles.map(function (r) {
            return h('li', null,
              h('div', { class: 'timeline__subrole' }, r.role),
              h('div', { class: 'timeline__when' }, when(r)),
              r.line ? h('p', { class: 'timeline__line' }, r.line) : null);
          })) : null,
          todos(e.todo)
        );
      });
    },

    education: function (items) {
      return items.map(function (e) {
        return h('li', null,
          h('div', { class: 'timeline__role' }, e.degree),
          h('div', { class: 'timeline__org' }, e.org),
          h('div', { class: 'timeline__when' }, e.dates),
          e.line ? h('p', { class: 'timeline__line' }, e.line) : null
        );
      });
    },

    writing: function (items) {
      return items.map(function (w) {
        var meta = [w.role, w.venue, w.date].filter(Boolean).join(' · ');
        return h('li', null,
          h('span', { class: 'writing__title' }, w.title),
          h('span', { class: 'writing__meta' }, meta),
          todos(w.todo),
          links(w.links)
        );
      });
    }
  };

  function showFallbacks() {
    document.querySelectorAll('noscript[data-fallback]').forEach(function (ns) {
      var box = document.querySelector('[data-render="' + ns.getAttribute('data-fallback') + '"]');
      if (box && !box.childNodes.length) {
        var div = document.createElement('div');
        div.innerHTML = ns.textContent;
        ns.replaceWith(div);
      }
    });
  }

  // Light/dark toggle. Light is the default; the choice is remembered in localStorage.
  // To keep the site light only, set data-theme-toggle="off" on <html> in index.html:
  // the button stays hidden and saved choices are ignored (see also the inline script in <head>).
  var root = document.documentElement;
  var toggle = document.getElementById('theme-toggle');

  // The project sites under dlamagna.github.io (AgenTraffic, Edge-Healer, Margin) each keep their own
  // light/dark choice in localStorage. They share this site's origin, so writing this site's theme
  // under their keys makes them open in the same theme as the page the visitor came from.
  var PROJECT_THEME_KEYS = ['agentraffic-theme', 'edge-healer-theme', 'margin-theme'];
  function shareTheme(dark) {
    PROJECT_THEME_KEYS.forEach(function (k) {
      try { localStorage.setItem(k, dark ? 'dark' : 'light'); } catch (err) { /* storage blocked */ }
    });
  }
  var themeColor = document.querySelector('meta[name="theme-color"]');
  function applyTheme(dark) {
    if (dark) root.setAttribute('data-theme', 'dark'); else root.removeAttribute('data-theme');
    if (toggle) toggle.setAttribute('aria-pressed', dark ? 'true' : 'false');
    if (themeColor) themeColor.setAttribute('content', dark ? '#0d1117' : '#ffffff');
    shareTheme(dark);
  }
  if (toggle && root.getAttribute('data-theme-toggle') !== 'off') {
    toggle.hidden = false;
    applyTheme(root.getAttribute('data-theme') === 'dark');
    toggle.addEventListener('click', function () {
      var dark = root.getAttribute('data-theme') !== 'dark';
      applyTheme(dark);
      try { localStorage.setItem('theme', dark ? 'dark' : 'light'); } catch (err) { /* storage blocked: the choice lasts for this page only */ }
    });
  } else {
    shareTheme(false); // toggle off: the site is light only, so the project sites open light too
  }

  if (document.querySelector('[data-render]')) fetch('data/projects.json')
    .then(function (r) { if (!r.ok) throw new Error(r.status); return r.json(); })
    .then(function (data) {
      document.querySelectorAll('[data-render]').forEach(function (box) {
        var key = box.getAttribute('data-render');
        if (render[key] && data[key]) append(box, render[key](data[key]));
      });
    })
    .catch(showFallbacks);
})();
